given.script:
%dw 2.0
output application/json
var csv = write([{sku: "A1", qty: 2, price: 9.5}, {sku: "B2", qty: 1, price: 20}], "application/csv")
var rows = read(csv, "application/csv")
---
sum(rows map ((r) -> (r.qty as Number) * (r.price as Number)))

